/**
 * Phase 11 — Institution Action Items page.
 *
 * Allows institutions to view, manage, and act on placement operation action items.
 * Action items are auto-generated by the system for critical placement operations
 * like students at risk, drives with low registrations, pending verifications, etc.
 *
 * Features:
 *   - List action items with severity/status/type filtering
 *   - Acknowledge, start, resolve, or dismiss items
 *   - Run auto-detection to generate new items
 *   - See recommended actions and CTA paths
 */

import { useState } from 'react';
import {
  FiCheckCircle,
  FiXCircle,
  FiClock,
  FiPlay,
  FiZap,
  FiRefreshCw,
  FiAlertCircle,
} from 'react-icons/fi';
import PageHeader from '@/components/ui/PageHeader';
import Card from '@/components/ui/Card';
import Button from '@/components/ui/Button';
import Select from '@/components/ui/Select';
import Badge from '@/components/ui/Badge';
import Modal from '@/components/ui/Modal';
import EmptyState from '@/components/ui/EmptyState';
import ErrorState from '@/components/ui/ErrorState';
import { SkeletonCard } from '@/components/ui/Skeleton';
import { toast } from 'sonner';
import {
  useActionItems,
  useAcknowledgeActionItem,
  useStartActionItem,
  useResolveActionItem,
  useDismissActionItem,
  useDetectActionItems,
  type PlacementActionItem,
} from '@/hooks/queries/useActionItems';

const SEVERITY_ORDER = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'] as const;

const SEVERITY_BADGE: Record<string, 'danger' | 'warning' | 'info' | 'default'> = {
  CRITICAL: 'danger',
  HIGH: 'warning',
  MEDIUM: 'info',
  LOW: 'default',
};

const STATUS_BADGE: Record<string, 'success' | 'info' | 'warning' | 'default' | 'danger'> = {
  OPEN: 'warning',
  ACKNOWLEDGED: 'info',
  IN_PROGRESS: 'warning',
  RESOLVED: 'success',
  DISMISSED: 'default',
};

const STATUS_LABEL: Record<string, string> = {
  OPEN: 'Open',
  ACKNOWLEDGED: 'Acknowledged',
  IN_PROGRESS: 'In Progress',
  RESOLVED: 'Resolved',
  DISMISSED: 'Dismissed',
};

const TYPE_LABEL: Record<string, string> = {
  LOW_REGISTRATION: 'Low Registration',
  PLACEMENT_AT_RISK: 'Placement at Risk',
  PENDING_VERIFICATION: 'Pending Verification',
  DRIVE_DEADLINE_APPROACHING: 'Deadline Approaching',
  UNVERIFIED_OFFER: 'Unverified Offer',
  STUDENT_INELIGIBLE: 'Student Ineligible',
  DOCUMENT_EXPIRED: 'Document Expired',
  SKILL_GAP_ALERT: 'Skill Gap Alert',
};

const SEVERITY_FILTER = [
  { value: '', label: 'All severities' },
  { value: 'CRITICAL', label: 'Critical' },
  { value: 'HIGH', label: 'High' },
  { value: 'MEDIUM', label: 'Medium' },
  { value: 'LOW', label: 'Low' },
];

const STATUS_FILTER = [
  { value: '', label: 'All statuses' },
  { value: 'OPEN', label: 'Open' },
  { value: 'ACKNOWLEDGED', label: 'Acknowledged' },
  { value: 'IN_PROGRESS', label: 'In Progress' },
  { value: 'RESOLVED', label: 'Resolved' },
  { value: 'DISMISSED', label: 'Dismissed' },
];

const TYPE_FILTER = [
  { value: '', label: 'All types' },
  { value: 'LOW_REGISTRATION', label: 'Low Registration' },
  { value: 'PLACEMENT_AT_RISK', label: 'Placement at Risk' },
  { value: 'PENDING_VERIFICATION', label: 'Pending Verification' },
  { value: 'DRIVE_DEADLINE_APPROACHING', label: 'Deadline Approaching' },
  { value: 'UNVERIFIED_OFFER', label: 'Unverified Offer' },
  { value: 'STUDENT_INELIGIBLE', label: 'Student Ineligible' },
  { value: 'DOCUMENT_EXPIRED', label: 'Document Expired' },
  { value: 'SKILL_GAP_ALERT', label: 'Skill Gap Alert' },
];

/* ── Resolve Modal ──────────────────────────────────────────────────── */

interface ResolveModalProps {
  item: PlacementActionItem;
  onClose: () => void;
  onResolve: (id: string, note?: string) => void;
  onDismiss: (id: string, note?: string) => void;
  isPending: boolean;
}

function ResolveModal({ item, onClose, onResolve, onDismiss, isPending }: ResolveModalProps) {
  const [note, setNote] = useState('');

  return (
    <Modal open onClose={onClose} title="Resolve Action Item" size="md">
      <div className="px-6 py-4 space-y-4">
        <div className="p-3 rounded-lg bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-sm font-semibold text-slate-900 dark:text-slate-100">{item.title}</span>
            <Badge variant={SEVERITY_BADGE[item.severity] ?? 'default'} size="sm">
              {item.severity}
            </Badge>
          </div>
          <p className="text-sm text-slate-600 dark:text-slate-300">{item.reason}</p>
        </div>
        {item.recommendedAction && (
          <div className="p-3 rounded-lg bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-800">
            <p className="text-xs font-semibold text-indigo-700 dark:text-indigo-400 uppercase mb-1">Recommended Action</p>
            <p className="text-sm text-indigo-700 dark:text-indigo-300">{item.recommendedAction}</p>
          </div>
        )}
        <div className="flex flex-col gap-1">
          <label className="text-xs font-medium text-slate-600 dark:text-slate-400">Resolution Note (optional)</label>
          <textarea
            value={note}
            onChange={(e) => setNote(e.target.value)}
            placeholder="Add a note about how this was resolved..."
            rows={3}
            className="w-full rounded-lg border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-900 px-3 py-2 text-sm text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-indigo-500"
          />
        </div>
      </div>
      <div className="flex gap-3 justify-end px-6 py-4 border-t border-slate-200 dark:border-slate-800">
        <Button variant="outline" onClick={onClose} disabled={isPending}>Cancel</Button>
        <Button
          variant="outline"
          onClick={() => { onDismiss(item.id, note || undefined); }}
          disabled={isPending}
        >
          Dismiss
        </Button>
        <Button
          variant="primary"
          onClick={() => { onResolve(item.id, note || undefined); }}
          loading={isPending}
        >
          Mark Resolved
        </Button>
      </div>
    </Modal>
  );
}

/* ── Item Card ──────────────────────────────────────────────────────── */

interface ActionItemCardProps {
  item: PlacementActionItem;
  onAcknowledge: (id: string) => void;
  onStart: (id: string) => void;
  onResolve: (item: PlacementActionItem) => void;
  onDismiss: (item: PlacementActionItem) => void;
  isPending: boolean;
}

function ActionItemCard({
  item,
  onAcknowledge,
  onStart,
  onResolve,
  onDismiss,
  isPending,
}: ActionItemCardProps) {
  const isOpen = item.status === 'OPEN';
  const isAcknowledged = item.status === 'ACKNOWLEDGED';
  const isInProgress = item.status === 'IN_PROGRESS';
  const isDone = item.status === 'RESOLVED' || item.status === 'DISMISSED';

  return (
    <div
      className={`rounded-xl border p-4 space-y-3 transition-all ${
        isDone
          ? 'border-slate-200 dark:border-slate-800 opacity-60'
          : item.severity === 'CRITICAL'
          ? 'border-rose-300 dark:border-rose-800 bg-rose-50/30 dark:bg-rose-900/10'
          : item.severity === 'HIGH'
          ? 'border-amber-300 dark:border-amber-800 bg-amber-50/30 dark:bg-amber-900/10'
          : 'border-slate-200 dark:border-slate-800'
      }`}
    >
      {/* Header */}
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2 flex-wrap">
          <Badge variant={SEVERITY_BADGE[item.severity] ?? 'default'} size="sm">
            {item.severity}
          </Badge>
          <Badge variant={STATUS_BADGE[item.status] ?? 'default'} size="sm">
            {STATUS_LABEL[item.status] ?? item.status}
          </Badge>
          <Badge variant="default" size="sm">{TYPE_LABEL[item.type] ?? item.type}</Badge>
        </div>
        {item.dueAt && !isDone && (
          <span className="flex items-center gap-1 text-xs text-slate-500 dark:text-slate-400">
            <FiClock className="w-3 h-3" />
            {new Date(item.dueAt).toLocaleDateString()}
          </span>
        )}
      </div>

      {/* Title & reason */}
      <div>
        <h3 className="font-semibold text-slate-900 dark:text-slate-100">{item.title}</h3>
        <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">{item.reason}</p>
      </div>

      {/* Drive context */}
      {item.drive && (
        <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
          <FiZap className="w-3 h-3" />
          <span>Drive: {item.drive.title}</span>
        </div>
      )}

      {/* Student context */}
      {item.student && (
        <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
          <FiAlertCircle className="w-3 h-3" />
          <span>Student: {item.student.name ?? item.student.email}</span>
        </div>
      )}

      {/* Recommended action */}
      {item.recommendedAction && !isDone && (
        <div className="p-2.5 rounded-lg bg-indigo-50/60 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-800">
          <p className="text-xs font-medium text-indigo-700 dark:text-indigo-400">{item.recommendedAction}</p>
        </div>
      )}

      {/* Resolution note */}
      {item.resolutionNote && (
        <div className="p-2.5 rounded-lg bg-slate-100 dark:bg-slate-800">
          <p className="text-xs text-slate-500 dark:text-slate-400">Resolution: {item.resolutionNote}</p>
        </div>
      )}

      {/* Actions */}
      {!isDone && (
        <div className="flex items-center gap-2 pt-2 border-t border-slate-100 dark:border-slate-800">
          {isOpen && (
            <Button
              variant="outline"
              size="sm"
              iconLeft={<FiCheckCircle className="w-3 h-3" />}
              onClick={() => onAcknowledge(item.id)}
              disabled={isPending}
            >
              Acknowledge
            </Button>
          )}
          {(isOpen || isAcknowledged) && (
            <Button
              variant="outline"
              size="sm"
              iconLeft={<FiPlay className="w-3 h-3" />}
              onClick={() => onStart(item.id)}
              disabled={isPending}
            >
              Start
            </Button>
          )}
          {isInProgress && (
            <Button
              variant="primary"
              size="sm"
              iconLeft={<FiCheckCircle className="w-3 h-3" />}
              onClick={() => onResolve(item)}
              disabled={isPending}
            >
              Resolve
            </Button>
          )}
          {(isOpen || isAcknowledged || isInProgress) && (
            <Button
              variant="ghost"
              size="sm"
              iconLeft={<FiXCircle className="w-3 h-3" />}
              onClick={() => onDismiss(item)}
              disabled={isPending}
              className="ml-auto"
            >
              Dismiss
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

/* ── Main Page ─────────────────────────────────────────────────────── */

export default function InstitutionActionItems() {
  const [severity, setSeverity] = useState('');
  const [status, setStatus] = useState('');
  const [type, setType] = useState('');
  const [resolvingItem, setResolvingItem] = useState<PlacementActionItem | null>(null);
  const [dismissingItem, setDismissingItem] = useState<PlacementActionItem | null>(null);

  const { data, isLoading, isError, refetch } = useActionItems({
    severity: severity || undefined,
    status: status || undefined,
    type: type || undefined,
  });

  const acknowledge = useAcknowledgeActionItem();
  const start = useStartActionItem();
  const resolve = useResolveActionItem();
  const dismiss = useDismissActionItem();
  const detect = useDetectActionItems();

  const items = data?.data ?? [];
  const isPending = acknowledge.isPending || start.isPending || resolve.isPending || dismiss.isPending;

  // Sort: CRITICAL > HIGH > MEDIUM > LOW, then by status (open first)
  const sortedItems = [...items].sort((a, b) => {
    const sevA = SEVERITY_ORDER.indexOf(a.severity as typeof SEVERITY_ORDER[number]);
    const sevB = SEVERITY_ORDER.indexOf(b.severity as typeof SEVERITY_ORDER[number]);
    if (sevA !== sevB) return sevA - sevB;
    const statusOrder: Record<string, number> = { OPEN: 0, ACKNOWLEDGED: 1, IN_PROGRESS: 2, RESOLVED: 3, DISMISSED: 4 };
    return (statusOrder[a.status] ?? 5) - (statusOrder[b.status] ?? 5);
  });

  const openItems = sortedItems.filter((i) => i.status === 'OPEN' || i.status === 'ACKNOWLEDGED' || i.status === 'IN_PROGRESS');
  const doneItems = sortedItems.filter((i) => i.status === 'RESOLVED' || i.status === 'DISMISSED');

  function handleAcknowledge(id: string) {
    acknowledge.mutate(id, {
      onSuccess: () => toast.success('Acknowledged', { description: 'Action item acknowledged.' }),
      onError: (err: unknown) => toast.error(err instanceof Error ? err.message : 'Unknown error'),
    });
  }

  function handleStart(id: string) {
    start.mutate(id, {
      onSuccess: () => toast.success('Started', { description: 'Working on this item.' }),
      onError: (err: unknown) => toast.error(err instanceof Error ? err.message : 'Unknown error'),
    });
  }

  function handleResolve(id: string, note?: string) {
    resolve.mutate(
      { id, resolutionNote: note },
      {
        onSuccess: () => {
          toast.success('Resolved', { description: 'Action item marked as resolved.' });
          setResolvingItem(null);
        },
        onError: (err: unknown) => toast.error(err instanceof Error ? err.message : 'Unknown error'),
      },
    );
  }

  function handleDismiss(id: string, note?: string) {
    dismiss.mutate(
      { id, resolutionNote: note },
      {
        onSuccess: () => {
          toast.success('Dismissed', { description: 'Action item dismissed.' });
          setDismissingItem(null);
        },
        onError: (err: unknown) => toast.error(err instanceof Error ? err.message : 'Unknown error'),
      },
    );
  }

  function handleDetect() {
    detect.mutate(undefined, {
      onSuccess: (result) => {
        const d = result as { created?: number; updated?: number };
        toast.success('Detection complete', {
          description: `Created: ${d.created ?? 0}, Updated: ${d.updated ?? 0} items.`,
        });
        void refetch();
      },
      onError: (err: unknown) => toast.error(err instanceof Error ? err.message : 'Unknown error'),
    });
  }

  return (
    <div className="container-page py-8 space-y-6">
      <PageHeader
        title="Action Items"
        subtitle="Operational alerts for placement drives. Manage student interventions, low-registration warnings, and verification tasks."
        actions={
          <Button
            variant="primary"
            iconLeft={<FiRefreshCw className={`w-4 h-4 ${detect.isPending ? 'animate-spin' : ''}`} />}
            onClick={handleDetect}
            loading={detect.isPending}
          >
            Detect Items
          </Button>
        }
      />

      {/* Filters */}
      <div className="flex flex-wrap gap-3">
        <Select
          options={SEVERITY_FILTER}
          value={severity}
          onChange={(e) => setSeverity(e.target.value)}
          className="w-40"
        />
        <Select
          options={STATUS_FILTER}
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          className="w-40"
        />
        <Select
          options={TYPE_FILTER}
          value={type}
          onChange={(e) => setType(e.target.value)}
          className="w-48"
        />
      </div>

      {isError && <ErrorState onRetry={refetch} />}

      {/* Summary stats */}
      {!isLoading && items.length > 0 && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {[
            { label: 'Critical', count: items.filter((i) => i.severity === 'CRITICAL' && i.status !== 'RESOLVED' && i.status !== 'DISMISSED').length, color: 'text-rose-600' },
            { label: 'High', count: items.filter((i) => i.severity === 'HIGH' && i.status !== 'RESOLVED' && i.status !== 'DISMISSED').length, color: 'text-amber-600' },
            { label: 'Open', count: openItems.length, color: 'text-slate-700 dark:text-slate-300' },
            { label: 'Resolved', count: doneItems.length, color: 'text-emerald-600' },
          ].map((s) => (
            <div key={s.label} className="bg-white dark:bg-slate-900 rounded-lg border border-slate-200 dark:border-slate-800 p-3 text-center">
              <div className={`text-2xl font-bold ${s.color}`}>{s.count}</div>
              <div className="text-xs text-slate-500 dark:text-slate-400">{s.label}</div>
            </div>
          ))}
        </div>
      )}

      {/* Action items */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {Array.from({ length: 4 }).map((_, i) => <SkeletonCard key={i} />)}
        </div>
      ) : sortedItems.length === 0 ? (
        <EmptyState
          icon={<FiCheckCircle />}
          title="No action items"
          description="All clear! There are no placement operation alerts at this time."
        />
      ) : (
        <div className="space-y-6">
          {/* Active items */}
          {openItems.length > 0 && (
            <div className="space-y-4">
              <h2 className="text-sm font-semibold text-slate-700 dark:text-slate-300 uppercase tracking-wide">
                Active ({openItems.length})
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {openItems.map((item) => (
                  <ActionItemCard
                    key={item.id}
                    item={item}
                    onAcknowledge={handleAcknowledge}
                    onStart={handleStart}
                    onResolve={(i) => setResolvingItem(i)}
                    onDismiss={(i) => setDismissingItem(i)}
                    isPending={isPending}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Resolved items */}
          {doneItems.length > 0 && (
            <div className="space-y-4">
              <h2 className="text-sm font-semibold text-slate-700 dark:text-slate-300 uppercase tracking-wide">
                Resolved / Dismissed ({doneItems.length})
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {doneItems.map((item) => (
                  <ActionItemCard
                    key={item.id}
                    item={item}
                    onAcknowledge={handleAcknowledge}
                    onStart={handleStart}
                    onResolve={(i) => setResolvingItem(i)}
                    onDismiss={(i) => setDismissingItem(i)}
                    isPending={isPending}
                  />
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Resolve modal */}
      {resolvingItem && (
        <ResolveModal
          item={resolvingItem}
          onClose={() => setResolvingItem(null)}
          onResolve={handleResolve}
          onDismiss={handleDismiss}
          isPending={isPending}
        />
      )}

      {/* Dismiss modal */}
      {dismissingItem && (
        <ResolveModal
          item={dismissingItem}
          onClose={() => setDismissingItem(null)}
          onResolve={handleResolve}
          onDismiss={handleDismiss}
          isPending={isPending}
        />
      )}
    </div>
  );
}
